void developerRequest(const std::string& action,const std::string& method,const std::string& path,const json& payload=json::object()){
 if(!developer())throw std::runtime_error("개발자 계정으로 로그인하세요.");if(developerBusy)throw std::runtime_error("이전 관리 요청을 처리 중입니다.");if(developerThread.joinable())developerThread.join();developerBusy=true;developerCancel=false;auto cfg=store->settings;auto* e=engine;
 developerThread=std::thread([this,cfg,e,action,method,path,payload]{try{NetworkScope scope(&developerCancel,std::chrono::steady_clock::now()+std::chrono::seconds(60));auto response=request(method,joinUrl(str(cfg,"api"),path),str(cfg,"api_key"),method=="GET"?"":payload.dump(),"application/json",&developerCancel,action=="original"?64*1024*1024:2*1024*1024,60000);if(response.code==429)throw std::runtime_error("요청 제한입니다. 잠시 후 다시 시도하세요.");json result;if(action=="original"){auto output=fs::path(wide(str(cfg,"output")))/("admin_"+id()+".png");saveImage(output,response.data);result={{"file",utf8(output.wstring())}};}else result=response.object();e->event({"developer_reply","",action,result});}catch(const std::exception& x){e->event({"developer_reply","","failed",{{"message",x.what()}}});}});
}
