 if(developerRows.empty()){std::wstring text=L"조회 결과가 없습니다. 새로고침을 누르세요.";LVITEMW item{};item.mask=LVIF_TEXT;item.pszText=text.data();SendMessageW(positive,LVM_INSERTITEMW,0,(LPARAM)&item);}
